#!/usr/bin/env python3
"""Merge coverage profiles generated by disjoint Go package shards."""

from __future__ import annotations

import sys
from pathlib import Path


def merge_profiles(profiles: list[Path], output: Path) -> None:
    """Write one coverage profile and reject missing or inconsistent shards."""
    if not profiles:
        raise ValueError("no coverage profiles were provided")
    mode = ""
    blocks: list[str] = []
    for profile in profiles:
        lines = profile.read_text(encoding="utf-8").splitlines()
        if not lines or not lines[0].startswith("mode: "):
            raise ValueError(f"coverage profile is empty or has no mode: {profile.name}")
        current_mode = lines[0]
        if mode and current_mode != mode:
            raise ValueError("coverage modes differ between shards")
        mode = current_mode
        blocks.extend(line for line in lines[1:] if line)
    if not blocks:
        raise ValueError("coverage profiles contain no statements")
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(mode + "\n" + "\n".join(blocks) + "\n", encoding="utf-8")


def main() -> int:
    if len(sys.argv) < 3:
        print("Usage: merge_coverage.py OUTPUT PROFILE...", file=sys.stderr)
        return 2
    try:
        merge_profiles([Path(value) for value in sys.argv[2:]], Path(sys.argv[1]))
    except (OSError, ValueError) as error:
        print(f"coverage merge failed: {error}", file=sys.stderr)
        return 1
    print(f"Merged {len(sys.argv) - 2} Go coverage shard(s).")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
